GlassBatchFeederMaker.ironStock=16; GlassBatchFeederMaker.bronzeStock=12; GlassBatchFeederMaker.woodStock=12; GlassBatchFeederMaker.leatherStock=8; GlassBatchFeederMaker.silverStock=8; GlassBatchFeederMaker.goldStock=6; GlassBatchFeederMaker.jewelStock=4; GlassBatchFeederMaker.pearlStock=4
GlassBatchFeederMaker.productStock = {}; GlassBatchFeederMaker.buildings = {}; GlassBatchFeederMaker.maker = nil; GlassBatchFeederMaker.activeMaking = {}; GlassBatchFeederMaker.totalProducts = 0; GlassBatchFeederMaker.dayTimer = 0
function GlassBatchFeederMaker.init() GlassBatchFeederMaker.ironStock=16; GlassBatchFeederMaker.bronzeStock=12; GlassBatchFeederMaker.woodStock=12; GlassBatchFeederMaker.leatherStock=8; GlassBatchFeederMaker.silverStock=8; GlassBatchFeederMaker.goldStock=6; GlassBatchFeederMaker.jewelStock=4; GlassBatchFeederMaker.pearlStock=4; GlassBatchFeederMaker.productStock={}; GlassBatchFeederMaker.buildings={}; GlassBatchFeederMaker.maker=nil; GlassBatchFeederMaker.activeMaking={}; GlassBatchFeederMaker.totalProducts=0; GlassBatchFeederMaker.dayTimer=0; print("[GlassBatchFeederMaker] Royal Glass Batch Feeder Maker System initialized (6 products, 4 buildings)") end
function GlassBatchFeederMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassBatchFeederMaker.maker={name=n or ("Dajalnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dajalnik najet: %s (spretnost: %d)",GlassBatchFeederMaker.maker.name,s),"success") end; return true end
function GlassBatchFeederMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassBatchFeederMaker.build(id) local ok,e=GlassBatchFeederMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassBatchFeederMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassBatchFeederMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassBatchFeederMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassBatchFeederMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassBatchFeederMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassBatchFeederMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassBatchFeederMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassBatchFeederMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassBatchFeederMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassBatchFeederMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassBatchFeederMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassBatchFeederMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassBatchFeederMaker.buildings==0 then return false,"Potrebna dajalna delavnica" end; if not GlassBatchFeederMaker.maker then return false,"Potreben dajalnik" end; return true end
function GlassBatchFeederMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassBatchFeederMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassBatchFeederMaker.ironStock=GlassBatchFeederMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassBatchFeederMaker.bronzeStock=GlassBatchFeederMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassBatchFeederMaker.woodStock=GlassBatchFeederMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassBatchFeederMaker.leatherStock=GlassBatchFeederMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassBatchFeederMaker.silverStock=GlassBatchFeederMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassBatchFeederMaker.goldStock=GlassBatchFeederMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassBatchFeederMaker.jewelStock=GlassBatchFeederMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassBatchFeederMaker.pearlStock=GlassBatchFeederMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassBatchFeederMaker.maker then t=math.max(1,t-math.floor(GlassBatchFeederMaker.maker.skill/13)) end; table.insert(GlassBatchFeederMaker.activeMaking,{id="glassbatchfeeder_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassBatchFeederMaker.completeMaking(m) local q=1.0+(GlassBatchFeederMaker.getQualityBonus()/100); if GlassBatchFeederMaker.maker then q=q+(GlassBatchFeederMaker.maker.skill/140) end; q=math.min(2.5,q); GlassBatchFeederMaker.productStock[m.productType]=(GlassBatchFeederMaker.productStock[m.productType] or 0)+m.quantity; GlassBatchFeederMaker.totalProducts=GlassBatchFeederMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassBatchFeederMaker.maker then GlassBatchFeederMaker.maker.itemsMade=GlassBatchFeederMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassBatchFeederMaker.maker.skill=math.min(100,GlassBatchFeederMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dajalnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassbatchfeeder.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassBatchFeederMaker.update(dt) if not _G.state then return end; GlassBatchFeederMaker.dayTimer=GlassBatchFeederMaker.dayTimer+dt; if GlassBatchFeederMaker.dayTimer>=30 then GlassBatchFeederMaker.dayTimer=0; for i=#GlassBatchFeederMaker.activeMaking,1,-1 do local m=GlassBatchFeederMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassBatchFeederMaker.completeMaking(m); table.remove(GlassBatchFeederMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassBatchFeederMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassBatchFeederMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassBatchFeederMaker.getStats() return {ironStock=GlassBatchFeederMaker.ironStock,bronzeStock=GlassBatchFeederMaker.bronzeStock,woodStock=GlassBatchFeederMaker.woodStock,leatherStock=GlassBatchFeederMaker.leatherStock,silverStock=GlassBatchFeederMaker.silverStock,goldStock=GlassBatchFeederMaker.goldStock,jewelStock=GlassBatchFeederMaker.jewelStock,pearlStock=GlassBatchFeederMaker.pearlStock,productStock=GlassBatchFeederMaker.productStock,numBuildings=#GlassBatchFeederMaker.buildings,hasMaker=GlassBatchFeederMaker.maker~=nil,makerName=GlassBatchFeederMaker.maker and GlassBatchFeederMaker.maker.name or "—",makerSkill=GlassBatchFeederMaker.maker and GlassBatchFeederMaker.maker.skill or 0,activeMaking=#GlassBatchFeederMaker.activeMaking,totalProducts=GlassBatchFeederMaker.totalProducts} end
return GlassBatchFeederMaker
